options.styles:
.pokedex-frame {
  background: #dc0a2d;
  border-radius: 18px 18px 12px 12px;
  padding: 16px;
  max-width: 320px;
  margin: 0 auto;
  font-family: 'Courier New', monospace;
  border: 3px solid #a00820;
  box-shadow:
    inset 0 3px 6px rgba(255,255,255,0.25),
    inset 0 -4px 10px rgba(0,0,0,0.45),
    0 10px 28px rgba(0,0,0,0.65);
}

.pokedex-header {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 10px;
}

.main-lens {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #8ad4f8, #1a6fb8, #0a3a70);
  border: 4px solid #fff;
  box-shadow:
    0 0 0 2px #a0c0e0,
    0 0 14px rgba(26,111,184,0.9),
    inset 0 0 10px rgba(0,0,0,0.4);
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
}

.lens-inner {
  position: absolute;
  top: 8px; left: 8px;
  width: 24px; height: 24px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.55), transparent);
}

.lens-shine {
  position: absolute;
  top: 7px; left: 11px;
  width: 11px; height: 6px;
  border-radius: 50%;
  background: rgba(255,255,255,0.75);
  transform: rotate(-30deg);
}

.leds { display: flex; gap: 7px; }

.led {
  width: 13px; height: 13px;
  border-radius: 50%;
}

.led-red    { background: #ff4444; box-shadow: 0 0 8px 3px #ff0000; }
.led-yellow { background: #ffcc00; box-shadow: 0 0 8px 3px #ffaa00; }
.led-green  { background: #44ff44; box-shadow: 0 0 8px 3px #00cc00; }

.pokedex-number {
  text-align: right;
  color: #ffe066;
  font-size: 13px;
  font-weight: bold;
  letter-spacing: 1px;
  text-shadow: 0 0 6px rgba(255,220,0,0.8);
  margin-bottom: 8px;
}

.screen-container {
  background: #1a1a1a;
  border-radius: 10px;
  padding: 6px;
  border: 4px solid #777;
  box-shadow:
    inset 0 0 14px rgba(0,0,0,0.9),
    0 0 0 2px #444,
    0 5px 10px rgba(0,0,0,0.5);
  margin-bottom: 12px;
}

.screen-inner {
  background: linear-gradient(160deg, #182818 0%, #263e26 45%, #1c3020 100%);
  border-radius: 6px;
  padding: 12px;
  min-height: 130px;
  position: relative;
  overflow: hidden;
}

.screen-inner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0,0,0,0.1) 2px,
    rgba(0,0,0,0.1) 4px
  );
  pointer-events: none;
  z-index: 0;
}

.screen-content {
  display: flex;
  align-items: center;
  gap: 12px;
  position: relative;
  z-index: 1;
}

.pokemon-image {
  width: 96px;
  height: 96px;
  object-fit: contain;
  image-rendering: pixelated;
  filter: drop-shadow(0 0 10px rgba(100,255,100,0.55));
  flex-shrink: 0;
}

.pokemon-info { flex: 1; }

.pokemon-name-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}

.pokemon-name {
  color: #a8ff78;
  font-size: 15px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  text-shadow: 0 0 10px rgba(168,255,120,0.75);
}

.mega-badge {
  background: linear-gradient(135deg, #9b59b6, #6c3483);
  color: #fff;
  font-size: 9px;
  font-weight: bold;
  padding: 2px 5px;
  border-radius: 3px;
  letter-spacing: 1px;
  box-shadow: 0 0 7px rgba(155,89,182,0.85);
}

.type-badges { display: flex; gap: 6px; flex-wrap: wrap; }

.type-badge {
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: bold;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  box-shadow: 0 2px 5px rgba(0,0,0,0.45);
}

.type-Normal   { background: #8a8a6a; }
.type-Fire     { background: #e25822; }
.type-Water    { background: #1a6fbc; }
.type-Grass    { background: #5d9e4f; }
.type-Electric { background: #d4ac00; color: #111; }
.type-Ice      { background: #4ab8c4; }
.type-Fighting { background: #8c3224; }
.type-Poison   { background: #8b3fa8; }
.type-Ground   { background: #b4883c; }
.type-Flying   { background: #6070c0; }
.type-Psychic  { background: #c0396b; }
.type-Bug      { background: #7a8e20; }
.type-Rock     { background: #927c40; }
.type-Ghost    { background: #5a4870; }
.type-Dragon   { background: #4040c0; }
.type-Dark     { background: #3d3244; }
.type-Steel    { background: #787888; }
.type-Fairy    { background: #d685ad; }

.stats-container {
  background: rgba(0,0,0,0.28);
  border-radius: 8px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: 1px solid rgba(255,255,255,0.1);
}

.stat-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stat-label {
  color: #fff;
  font-size: 10px;
  font-weight: bold;
  width: 26px;
  text-shadow: 0 1px 3px rgba(0,0,0,0.6);
}

.stat-bar-bg {
  flex: 1;
  height: 10px;
  background: rgba(0,0,0,0.55);
  border-radius: 5px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,0.08);
}

.stat-bar {
  height: 100%;
  border-radius: 5px;
  max-width: 100%;
}

.stat-atk {
  background: linear-gradient(90deg, #c05000, #ff8800, #ffcc44);
  box-shadow: 0 0 7px rgba(255,136,0,0.75);
}

.stat-def {
  background: linear-gradient(90deg, #0030a0, #1a6fdc, #66aaff);
  box-shadow: 0 0 7px rgba(26,111,220,0.75);
}

.stat-sta {
  background: linear-gradient(90deg, #005500, #22aa22, #66ff66);
  box-shadow: 0 0 7px rgba(34,170,34,0.75);
}

.stat-value {
  color: #ffe066;
  font-size: 10px;
  font-weight: bold;
  width: 24px;
  text-align: right;
  text-shadow: 0 0 5px rgba(255,220,0,0.65);
}

options.afterRender:
context.element
  .querySelectorAll('.pokemon-card')
  .forEach(function(card) {
    card.addEventListener('click', function() {
      var name = card.getAttribute('data-pokemon');
      context.grafana.locationService.partial({ 'var-textbox0': name });
    });
  });

