options.afterRender:
(function(){
  var s=context.panelData&&context.panelData.series;
  if(!s||!s.length)return;
  function vl(fr,nm){
    if(!fr||!fr.fields)return[];
    var f=fr.fields.find(function(x){return x.name===nm;});
    if(!f||f.values==null)return[];
    var v=f.values;
    if(Array.isArray(v))return v;
    var a=[],n=v.length||0;
    for(var i=0;i<n;i++)a.push(v.get?v.get(i):v[i]);
    return a;
  }
  var sf=s[0];
  var atk=Number(vl(sf,'ataque_base')[0])||0;
  var def=Number(vl(sf,'defensa_base')[0])||0;
  var sta=Number(vl(sf,'stamina_base')[0])||0;
  var attacksRaw=vl(sf,'attacks')[0];
  var attacks=[];
  try{attacks=typeof attacksRaw==='string'?JSON.parse(attacksRaw):(attacksRaw||[]);}catch(e){}
  /* --- Pills --- */
  var pills=context.element.querySelector('.sp-pills');
  if(pills)pills.innerHTML='<span class="sp-pill atk-p">ATK '+atk+'</span><span class="sp-pill def-p">DEF '+def+'</span><span class="sp-pill sta-p">STA '+sta+'</span>';
  /* --- Canvas Radar --- */
  var canvas=context.element.querySelector('#sp-canvas');
  if(canvas&&canvas.getContext){
    var ctx=canvas.getContext('2d');
    var W=140,H=140,cx=70,cy=72,R=50;
    var axes=[
      {label:'ATK',val:atk,max:370,angle:-Math.PI/2,color:'#ff8800'},
      {label:'DEF',val:def,max:340,angle:Math.PI/6,color:'#4488ff'},
      {label:'STA',val:sta,max:500,angle:5*Math.PI/6,color:'#44cc44'}
    ];
    function pt(r,a){return{x:cx+r*Math.cos(a),y:cy+r*Math.sin(a)};}
    ctx.clearRect(0,0,W,H);
    for(var lv=1;lv<=4;lv++){
      ctx.beginPath();
      var rr=R*lv/4;
      ctx.moveTo(pt(rr,axes[0].angle).x,pt(rr,axes[0].angle).y);
      for(var ai=1;ai<axes.length;ai++){var p=pt(rr,axes[ai].angle);ctx.lineTo(p.x,p.y);}
      ctx.closePath();
      ctx.strokeStyle='rgba(255,255,255,'+(0.08+lv*0.04)+')';
      ctx.lineWidth=0.8;
      ctx.stroke();
    }
    axes.forEach(function(a){
      var p=pt(R,a.angle);
      ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(p.x,p.y);
      ctx.strokeStyle='rgba(255,255,255,0.22)';ctx.lineWidth=1;ctx.stroke();
    });
    ctx.beginPath();
    axes.forEach(function(a,i){
      var r=R*Math.min(a.val/a.max,1);
      var p=pt(r,a.angle);
      if(i===0)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y);
    });
    ctx.closePath();
    ctx.fillStyle='rgba(255,160,0,0.28)';
    ctx.fill();
    ctx.strokeStyle='#ffa500';
    ctx.lineWidth=2;
    ctx.stroke();
    axes.forEach(function(a){
      var r=R*Math.min(a.val/a.max,1);
      var p=pt(r,a.angle);
      ctx.beginPath();ctx.arc(p.x,p.y,4,0,2*Math.PI);
      ctx.fillStyle=a.color;ctx.fill();
      ctx.strokeStyle='#fff';ctx.lineWidth=1.2;ctx.stroke();
      var lp=pt(R+16,a.angle);
      ctx.font='bold 10px Courier New';
      ctx.fillStyle=a.color;
      ctx.textAlign='center';
      ctx.textBaseline='middle';
      ctx.fillText(a.label,lp.x,lp.y-3);
      ctx.font='9px Courier New';
      ctx.fillStyle='#ffe066';
      ctx.fillText(a.val,lp.x,lp.y+8);
    });
  }
  /* --- Attacks --- */
  var el=context.element.querySelector('.sp-moves');
  if(!el)return;
  if(!attacks||!attacks.length){el.innerHTML='<div class="sp-nd">Sin datos disponibles</div>';return;}
  var html='';
  for(var i=0;i<attacks.length;i++){
    var a=attacks[i];
    var dps=a.avg_dps?parseFloat(a.avg_dps).toFixed(1):'—';
    var bars=a.barras?'&#9646;'.repeat(Math.min(parseInt(a.barras),3)):'';
    html+='<div class="atk-card"><div class="atk-rk">#'+(i+1)+'</div>';
    html+='<div class="atk-mv">';
    html+='<div class="mv"><span class="mv-t t-'+a.tipoR+'">'+a.tipoR+'</span><span class="mv-n">'+a.rapido+'</span><span class="mv-d">&#9889;'+a.dmgR+'</span>'+(a.stabR?'<span class="stab">STAB</span>':'')+'</div>';
    html+='<div class="mv"><span class="mv-t t-'+a.tipoC+'">'+a.tipoC+'</span><span class="mv-n">'+a.cargado+'</span><span class="mv-d">'+a.dmgC+'</span>'+(bars?'<span class="enb">'+bars+'</span>':'')+(a.stabC?'<span class="stab">STAB</span>':'')+'</div>';
    html+='</div><div class="atk-dps">'+dps+'<br><span class="dps-l">DPS</span></div></div>';
  }
  el.innerHTML=html;
})();

