.sp-wrap{display:flex;gap:8px;padding:6px;height:100%;box-sizing:border-box;font-family:'Courier New',monospace;overflow:hidden}
.sp-left{flex-shrink:0;display:flex;flex-direction:column;align-items:center;gap:4px;width:168px}
.sp-right{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px;overflow-y:auto}
.sp-title{color:#ffe066;font-size:10px;font-weight:bold;text-transform:uppercase;letter-spacing:1px;border-bottom:1px solid rgba(255,220,0,0.3);padding-bottom:3px;width:100%;text-shadow:0 0 6px rgba(255,220,0,0.5);margin-bottom:2px}
.sp-radar-wrap{display:flex;align-items:center;justify-content:center}
.sp-pills{display:flex;gap:3px;flex-wrap:wrap;justify-content:center}
